# Patch 0010: client hint brand lists generated by the kernel.
# Sourced by server-test.sh, which provides run/field/check/differ/show and $WORK.

profile() {  # profile <file> <full version>
  cat > "$1" <<EOF
{
  "seed": "1",
  "userAgent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/${2%%.*}.0.0.0 Safari/537.36",
  "platform": "Win32",
  "uaData": {"brand": "Google Chrome", "fullVersion": "$2", "platform": "Windows",
             "platformVersion": "15.0.0", "architecture": "x86", "bitness": "64"}
}
EOF
}
profile "$WORK/c158.json" 158.0.8127.37
profile "$WORK/c157.json" 157.0.8103.51
cat > "$WORK/explicit.json" <<'EOF'
{"seed": "1", "uaData": {"platform": "Windows", "fullVersion": "158.0.8127.37",
  "brands": [{"brand": "Custom", "version": "7"}],
  "fullVersionList": [{"brand": "Custom", "version": "7.1.2.3"}]}}
EOF

decode() { python3 -c 'import sys, urllib.parse; print(urllib.parse.unquote(sys.argv[1]))' "$1"; }
count() { echo "$1" | tr ',' '\n' | grep -c .; }
has() { case ",$1," in *",$2,"*) echo yes ;; *) echo no ;; esac; }

PLAIN=$(run identity.html)
C158=$(run identity.html --proteus-config="$WORK/c158.json")
C157=$(run identity.html --proteus-config="$WORK/c157.json")
EXPL=$(run identity.html --proteus-config="$WORK/explicit.json")

PB=$(decode "$(field "$PLAIN" chBrands)")
B158=$(decode "$(field "$C158" chBrands)"); F158=$(decode "$(field "$C158" chFullList)")
B157=$(decode "$(field "$C157" chBrands)"); F157=$(decode "$(field "$C157" chFullList)")
# The version the kernel itself is, and the generated list for a profile of that version.
OWN=$(echo "$PB" | tr ',' '
' | grep '^Chromium/' | cut -d/ -f2)
case "$OWN" in 157) SAME=$B157 ;; *) SAME=$B158 ;; esac
echo "plain (Chromium $OWN) : $PB"
echo "Chrome 158 brands    : $B158"
echo "Chrome 158 full list : $F158"
echo "Chrome 157 brands    : $B157"
echo "Chrome 157 full list : $F157"
echo "Chrome 158 header    : $(decode "$(field "$C158" hdrCh)")"

# The GREASE entry of the plain browser, e.g. "Not.A/Brand/24".
GREASE=$(echo "$PB" | tr ',' '\n' | grep -v '^Chromium/')

check  "three brands are reported"                    "$(count "$B158")" 3
check  "Chromium with the major version"              "$(has "$B158" "Chromium/158")" yes
check  "the profile's brand with the major version"   "$(has "$B158" "Google Chrome/158")" yes
check  "the same GREASE brand a stock build of the kernel's version sends" "$(has "$SAME" "$GREASE")" yes
check  "full version list carries the full version"   "$(has "$F158" "Google Chrome/158.0.8127.37")" yes
check  "full version list has three entries"          "$(count "$F158")" 3
check  "worker sees the same platform"                "$(field "$C158" workerChPlatform)" "Windows"
case "$(decode "$(field "$C158" hdrCh)")" in
  *'"Google Chrome";v="158"'*) echo "ok   Sec-CH-UA header carries the generated brands" ;;
  *) echo "FAIL Sec-CH-UA header"; FAIL=1 ;;
esac

# Ground truth for another version: this is the list observed from a real Chrome 157
# identity. It checks the GREASE spelling, its version and the ordering together.
check  "version 157 gives the list a real Chrome 157 sends" \
       "$B157" "Not-A.Brand/99,Google Chrome/157,Chromium/157"
check  "version 157 full version list" \
       "$F157" "Not-A.Brand/99.0.0.0,Google Chrome/157.0.8103.51,Chromium/157.0.8103.51"
differ "the list depends on the version"              "$B157" "$B158"

check  "explicit brand lists are still honoured"      "$(decode "$(field "$EXPL" chBrands)")" "Custom/7"
check  "explicit full version list still honoured"    "$(decode "$(field "$EXPL" chFullList)")" "Custom/7.1.2.3"
